  /* ---------- doživljaji ---------- */
  "d.eyebrow": ["Experiences", "Experiențe"],
  "d.title": ["A day at the cellar, <em>an evening with wine</em>", "O zi la pivniță, <em>o seară cu vin</em>"],
  "d.lead": ["Tastings, a traditional table, celebrations and winegrowers' feast days, in the stone setting of the Rajac wine cellars.", "Degustări, masă tradițională, petreceri și sărbătorile viticultorilor, în decorul de piatră al pivnițelor din Rajac."],
  "d.x.eyebrow": ["What awaits you", "Ce vă așteaptă"],
  "d.x.title": ["Four reasons <em>to stay longer</em>", "Patru motive <em>să rămâneți mai mult</em>"],
  "d.e1.t": ["Tasting at the pimnica", "Degustare la pimnica"],
  "d.e1.d": ["Wines from a cellar dug into the earth, with the host's stories about the varieties, the region and the family. On the large terrace under the vines, or in the cool of the cellar when summer is at its hottest.", "Vinuri dintr-o pivniță săpată în pământ, însoțite de poveștile gazdei despre soiuri, ținut și familie. Pe terasa mare de sub viță sau în răcoarea pivniței când vara e cea mai fierbinte."],
  "d.e1.l": ["Our wines", "Vinurile noastre"],
  "d.e2.t": ["Traditional table", "Masa tradițională"],
  "d.e2.d": ["Dishes from grandmother's recipes made with local, organic ingredients: meat from our smokehouse, cheeses, gibanica, proja and kačamak.", "Bucate după rețetele bunicii, din ingrediente locale și organice: carne din afumătoarea noastră, brânzeturi, gibanica, proja și kačamak."],
  "d.e2.l": ["Menu", "Meniu"],
  "d.e3.t": ["Celebrations & gatherings", "Petreceri și evenimente"],
  "d.e3.d": ["Birthdays, weddings, business gatherings and groups — on the cellar terrace, in the ethno restaurant or in the cellar at the guesthouse.", "Zile de naștere, nunți, întâlniri de afaceri și grupuri — pe terasa pivniței, în restaurantul etno sau în pivnița de la pensiune."],
  "d.e3.l": ["Learn more", "Aflați mai multe"],
  "d.e4.t": ["Rest under the vines", "Odihnă sub viță"],
  "d.e4.d": ["A big swing with a beautiful view, a lounger in the shade of the vines and a stroll along stone lanes among two hundred wine cellars.", "Un leagăn mare cu o priveliște minunată, un șezlong la umbra viței și o plimbare pe ulițele de piatră printre două sute de pivnițe."],
  "d.e4.l": ["About the cellars", "Despre pivnițe"],
  "d.m.eyebrow": ["Menu", "Meniu"],
  "d.m.title": ["Flavours <em>beyond translation</em>", "Gusturi <em>fără traducere</em>"],
  "d.m.lead": ["Cooking is a special part of our tradition. For many of our specialities there is no proper word in other languages, and no taste to compare them with — so the best thing is to come and try them.", "Gătitul este o parte aparte a tradiției noastre. Pentru multe dintre specialitățile noastre nu există un cuvânt potrivit în alte limbi și nici un gust cu care să le compari — așa că cel mai bine e să veniți să le gustați."],
  "d.m1.t": ["Perić platter", "Platoul Perić"],
  "d.m1.d": ["A cold platter with pečenica, dried meat, smoked bacon and home-made cheese, pork cracklings, ajvar, ljutenica, pickled cucumbers and peppers, with wine and rakija to your liking.", "Platou rece cu pečenica, carne uscată, slănină afumată și brânză de casă, jumări, ajvar, ljutenica, castraveți și ardei murați, cu vin și rachiu după plac."],
  "d.m2.t": ["Meze", "Meze"],
  "d.m2.d": ["Pečenica, smoked bacon, dry-cured pork neck, prosciutto, kulen sausage and olives.", "Pečenica, slănină afumată, ceafă uscată, prosciutto, cârnat kulen și măsline."],
  "d.m3.t": ["Home-made cheeses", "Brânzeturi de casă"],
  "d.m3.d": ["Young and aged cow's cheese, sheep's and goat's cheese and kashkaval.", "Brânză de vacă tânără și maturată, brânză de oaie și de capră și cașcaval."],
  "d.m4.t": ["Tanjirača grill", "Grătar pe tanjirača"],
  "d.m4.d": ["Mixed meat cooked on a tanjirača griddle over the fire — pork chop, neck, sausage and skewers — with grilled vegetables.", "Carne asortată gătită pe tava tanjirača deasupra focului — cotlet, ceafă, cârnați și frigărui — cu legume la grătar."],
  "d.m5.t": ["Grilled mushrooms", "Ciuperci la grătar"],
  "d.m5.d": ["Button mushrooms and seasonal mushrooms from the grill.", "Ciuperci champignon și ciuperci de sezon la grătar."],
  "d.must": ["You must try", "Trebuie să gustați"],
  "d.mp1": ["with rakija & wine", "cu rachiu și vin"],
