  "d.k.eyebrow": ["Events", "Evenimente"],
  "d.k.title": ["Celebrations <em>in a stone setting</em>", "Petreceri <em>într-un decor de piatră</em>"],
  "d.k.lead": ["We organise all kinds of gatherings, celebrations and parties: in the natural setting of the cellar terrace, in the ethno restaurant or in the cellar at the guesthouse.", "Organizăm tot felul de întâlniri, petreceri și reuniuni: în decorul natural al terasei pivniței, în restaurantul etno sau în pivnița de la pensiune."],
  "d.k1.t": ["The cellar terrace", "Terasa pivniței"],
